WITH enriched AS (SELECT *, FIRST_VALUE(unit_price) IGNORE NULLS OVER (PARTITION BY order_id ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_unit_price, AVG(unit_price) OVER (ORDER BY quantity, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS unit_price_avg_2_prior, AVG(unit_price) OVER (PARTITION BY order_id, product_id) AS order_id_avg_unit_price, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY unit_price, id) AS row_seq, NTILE(5) OVER (ORDER BY unit_price, id) AS unit_price_bucket FROM order_items) SELECT product_id, APPROX_PERCENTILE(unit_price_bucket, 0.95) AS unit_price_bucket_p95, BIT_OR(quantity) AS quantity_bit_or, BIT_OR(quantity) AS quantity_bit_or_2 FROM enriched GROUP BY product_id ORDER BY product_id DESC
